import{_ as n,a0 as o,w as p,s as g,ao as l,I as s,a1 as e,A as r,x as i}from"./chunks/framework.ePQ6-oQR.js";import"./chunks/theme.D0YJYoYq.js";const C=JSON.parse('{"title":"aria2 与 wget ：选择你的下载管理器 | LCTT x X-CMD","titleTemplate":false,"description":"aria2 与 wget ：选择你的下载管理器 | LCTT (201701) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"aria2 与 wget ：选择你的下载管理器 | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"aria2 与 wget ：选择你的下载管理器 | LCTT (201701) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"201701/20150629 Aria2 Vs Wget – Choose your Download Manager","title":"aria2 与 wget ：选择你的下载管理器","tag":"201701","desc":""},"relativePath":"201701/20150629 Aria2 Vs Wget – Choose your Download Manager.md","filePath":"[post].md"}'),d={name:"201701/20150629 Aria2 Vs Wget – Choose your Download Manager.md"};function u(h,a,b,k,m,f){const t=o("Link");return p(),g("div",null,[a[14]||(a[14]=l('<h1 id="aria2-与-wget-选择你的下载管理器" tabindex="-1">aria2 与 wget ：选择你的下载管理器 <a class="header-anchor" href="#aria2-与-wget-选择你的下载管理器" aria-label="Permalink to “aria2 与 wget ：选择你的下载管理器”">​</a></h1><p>任何没有下载管理器的 Linux 操作系统是不完整的。多年来，基于 Linux 的发行版使用 wget 作为默认下载管理器。它是一个很棒的小程序，可以在命令行下工作，如果你需要安装东西、下载东西、运行 shell 脚本等，某种程度上都可以在 wget 中完成任务。在过去的很多年里，我们发现 wget 缺乏一些高级的功能，而它的替代品 ** aria2** ，由于满足了高级 Linux 用户的渴望而受到了许多用户的关注。我们将在本文中回顾 <strong>aria2</strong> 的安装过程以及 wget 和 aria2 之间的区别，因此你可以决定哪个下载管理器最符合你的需要。</p><h3 id="安装-aria2" tabindex="-1">安装 aria2 <a class="header-anchor" href="#安装-aria2" aria-label="Permalink to “安装 aria2”">​</a></h3><p><strong>在 Ubuntu/Debian 中安装 aria2：</strong></p><p>只要在 Ubuntu 中运行下面的命令安装：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>sudo apt-get install aria2</span></span></code></pre></div>',6)),s("p",null,[e(t,{href:"http://linuxpitstop.com/wp-content/uploads/2015/06/aria2.png"},{default:r(()=>[...a[0]||(a[0]=[s("img",{src:"http://linuxpitstop.com/wp-content/uploads/2015/06/aria2.png",alt:"aria2"},null,-1)])]),_:1})]),a[15]||(a[15]=l('<p><strong>在 Fedora/RHEL/Centos 中安装 aria2：</strong></p><p>运行下面的命令在 Fedora/RHEL 和基于 Centos 的系统中安装：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>sudo yum install aria2</span></span></code></pre></div><p><strong>在 Arch Linux 中安装 aria2：</strong></p><p>运行下面的命令在基于 Arch Linux 的系统中安装。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>sudo pacman -Sy aria2</span></span></code></pre></div><h3 id="aria2-的重要功能" tabindex="-1">aria2 的重要功能 <a class="header-anchor" href="#aria2-的重要功能" aria-label="Permalink to “aria2 的重要功能”">​</a></h3><p>让我们来讨论 aria2 中使它如此受欢迎的重要功能：</p><ul><li>通过使用多个连接下载文件，最大限度地利用可用带宽。</li><li>同时下载多个文件和同时下载的能力。</li><li>torrent 客户端提供的所有功能都可以在这个小程序中找到。</li><li>它提供 meta 链接下载。</li><li>支持使用 JSON-RPC 和 XML-RPC 协议的远程过程调用。</li><li>无需等待当前下载完成，轻松批量下载文件。</li></ul><h3 id="aria2-的一些副作用" tabindex="-1">aria2 的一些副作用: <a class="header-anchor" href="#aria2-的一些副作用" aria-label="Permalink to “aria2 的一些副作用:”">​</a></h3><p>aria2 的多线程机制可能会使目标服务器过载。相比下来 wget 就轻量级多了，wget 比 aria2 消耗资源少 20％。aria2 尚未经受 wget 那样巨大的使用规模的测试，因此可能完全准备好成为默认下载管理器。</p><h3 id="wget-的重要特性" tabindex="-1">wget 的重要特性 <a class="header-anchor" href="#wget-的重要特性" aria-label="Permalink to “wget 的重要特性”">​</a></h3><ul><li>当然它是最广泛使用和测试的下载管理器。</li><li>它是一个简单的程序，具有较少的功能，但稳定工作了几十年。</li><li>默认所有 Linux 发行版上都有，不需要繁重的安装。</li><li>与 aria2 相比更轻量级。</li></ul><h3 id="总结" tabindex="-1">总结 <a class="header-anchor" href="#总结" aria-label="Permalink to “总结”">​</a></h3><p>虽然 wget 没有丰富的功能，但仍然工作得相当不错，然而，高级用户肯定会喜欢 aria2，因为它满足更快和并发下载的需要。aria2 可能需要很长时间来取代 wget 成为默认下载管理器，而目前 wget 用在几乎所有 linux 发行版的安装程序脚本中。</p><hr>',16)),s("p",null,[a[2]||(a[2]=i("via: ",-1)),e(t,{href:"http://linuxpitstop.com/aria-2-vs-wget/"},{default:r(()=>[...a[1]||(a[1]=[i("http://linuxpitstop.com/aria-2-vs-wget/",-1)])]),_:1})]),s("p",null,[a[6]||(a[6]=i("作者：",-1)),e(t,{href:"http://linuxpitstop.com/author/aun/"},{default:r(()=>[...a[3]||(a[3]=[i("Aun",-1)])]),_:1}),a[7]||(a[7]=i(" 译者：",-1)),e(t,{href:"https://github.com/geekpi"},{default:r(()=>[...a[4]||(a[4]=[i("geekpi",-1)])]),_:1}),a[8]||(a[8]=i(" 校对：",-1)),e(t,{href:"https://github.com/wxy"},{default:r(()=>[...a[5]||(a[5]=[i("wxy",-1)])]),_:1})]),s("p",null,[a[11]||(a[11]=i("本文由 ",-1)),e(t,{href:"https://github.com/LCTT/TranslateProject"},{default:r(()=>[...a[9]||(a[9]=[i("LCTT",-1)])]),_:1}),a[12]||(a[12]=i(" 原创编译，",-1)),e(t,{href:"https://linux.cn/"},{default:r(()=>[...a[10]||(a[10]=[i("Linux中国",-1)])]),_:1}),a[13]||(a[13]=i(" 荣誉推出",-1))])])}const T=n(d,[["render",u]]);export{C as __pageData,T as default};
